function errText(e){return String((e&&e.message)||e||'未知错误');}
function pickList(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){
    const ks=['messages','items','list','data','results'];
    for(let i=0;i<ks.length;i++){if(Array.isArray(d[ks[i]]))return d[ks[i]];}
  }
  return [];
}
function txt(v){
  if(v==null)return '';
  if(typeof v==='string')return v;
  if(typeof v==='number')return String(v);
  if(Array.isArray(v))return v.map(txt).filter(Boolean).join(', ');
  if(typeof v==='object')return txt(v.name||v.display_name||v.address||v.email||'');
  return '';
}
function toDay(v){
  if(v==null||v==='')return '';
  const d=typeof v==='number'?new Date(v<1e12?v*1000:v):new Date(String(v));
  if(isNaN(d.getTime()))return '';
  const p=n=>String(n).padStart(2,'0');
  return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate());
}
function normMail(m,i){
  const o=(m&&typeof m==='object')?m:{};
  const subject=txt(o.subject||o.title||o.snippet)||'（无主题）';
  const from=txt(o.from||o.sender||o.from_name||o.from_address);
  const day=toDay(o.date||o.received_at||o.receivedAt||o.internal_date||o.internalDate||o.sent_at||o.timestamp||o.time);
  const id=txt(o.id||o.message_id||o.messageId||o.uid)||('m:'+subject+'|'+from+'|'+day+'|'+i);
  return {id:id,subject:subject,from:from,day:day};
}
function inRange(day,r){
  if(!day)return true;
  if(r.from&&day<r.from)return false;
  if(r.to&&day>r.to)return false;
  return true;
}
function byDayDesc(a,b){return a.day<b.day?1:(a.day>b.day?-1:0);}
function mailErr(e){
  const s=String(e||'');
  if(/permission|denied|bind|connect|unauth/i.test(s))return '邮箱尚未连接，请先在平台连接邮箱后再读取。（'+s+'）';
  return '读取失败，请稍后重试。（'+s+'）';
}
function localRun(ui,redraw){
  return async function(key,fn){
    ui.jobs=ui.jobs||{};
    if(ui.jobs[key]&&ui.jobs[key].status==='loading')return false;
    ui.jobs[key]={status:'loading'};redraw();
    try{const data=await fn();ui.jobs[key]={status:'ok',data:data};redraw();return true;}
    catch(e){ui.jobs[key]={status:'error',error:errText(e)};redraw();return false;}
  };
}
async function fetchSourceLocal(host,id){
  const r=await host.fetchData(id);
  if(r&&r.status==='ok'&&r.data&&typeof r.data==='object')return r.data;
  throw new Error((r&&(r.errorCode||r.error||r.status))||'no_data');
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,host,day}=ctx;
  const SRC='connected.mail.message-list';
  const runAsync=ctx.runAsync||localRun(ui,redraw);
  const fetchSource=ctx.fetchSource||(id=>fetchSourceLocal(host,id));
  const h=(t,a,...k)=>el(t,a||{},...k.flat().filter(x=>x!=null&&x!==false));
  const range=Object.assign({from:'',to:''},(state&&state.range)||{});
  const plan=(state&&state.plan)||{};
  ui.step=ui.step||1;
  const step=ui.step;
  const job=ui.mailN?(ui.jobs&&ui.jobs['mail'+ui.mailN]):null;
  const loading=!!(job&&job.status==='loading');
  const loaded=!!(job&&job.status==='ok');
  const all=loaded?pickList(job.data).map(normMail):Object.keys(plan).map(id=>({id:id,subject:plan[id].subject||'（无主题）',from:plan[id].from||'',day:plan[id].day||''}));
  const rows=all.filter(r=>inRange(r.day,range)).sort(byDayDesc);
  const picked=Object.keys(plan).filter(id=>plan[id].picked).map(id=>({id:id,subject:plan[id].subject||'（无主题）',from:plan[id].from||'',day:plan[id].day||'',reason:plan[id].reason||''})).filter(r=>inRange(r.day,range)).sort(byDayDesc);

  const fail=e=>{ui.notice={kind:'error',text:'保存失败，已保留原数据。'+errText(e)};redraw();};
  const setRange=(k,v)=>update(s=>{const o=Object.assign({from:'',to:''},(s&&s.range)||{});o[k]=v;return Object.assign({},s,{range:o});}).catch(fail);
  const quick=n=>update(s=>Object.assign({},s,{range:{from:toDay(Date.now()-n*86400000),to:day()}})).catch(fail);
  const setPlan=(r,patch)=>update(s=>{
    const p=Object.assign({},(s&&s.plan)||{});
    p[r.id]=Object.assign({},p[r.id]||{},{subject:r.subject,from:r.from,day:r.day},patch);
    return Object.assign({},s,{plan:p});
  }).catch(fail);
  const pickAll=on=>update(s=>{
    const p=Object.assign({},(s&&s.plan)||{});
    rows.forEach(r=>{p[r.id]=Object.assign({},p[r.id]||{},{subject:r.subject,from:r.from,day:r.day,picked:on});});
    return Object.assign({},s,{plan:p});
  }).catch(fail);
  const setMark=(r,m)=>{
    const cur=(plan[r.id]||{}).mark;
    const next=cur===m?'':m;
    return setPlan(r,{mark:next,picked:next==='archive'});
  };
  const go=n=>{ui.step=n;ui.notice=null;ui.open=null;redraw();};
  const readMails=async()=>{
    if(!range.from||!range.to){ui.notice={kind:'warn',text:'请先选好起始和结束日期。'};redraw();return;}
    if(range.from>range.to){ui.notice={kind:'warn',text:'起始日期不能晚于结束日期。'};redraw();return;}
    ui.notice=null;
    ui.mailN=(ui.mailN||0)+1;
    const ok=await runAsync('mail'+ui.mailN,()=>fetchSource(SRC));
    if(ok){ui.step=2;ui.open=null;redraw();}
  };
  const askAi=()=>{
    ui.notice={kind:'warn',text:'AI 建议未接入：平台目前没有 AI 推理接口，无法自动判断哪些邮件该归档、为什么。你可以在「审阅」里自己标记并填写理由。'};
    redraw();
  };
  const doArchive=()=>{
    ui.tried=true;
    ui.notice={kind:'warn',text:'归档未执行：平台目前没有邮件归档接口，没有任何邮件被改动，所以也没有成功或失败记录。你的勾选和理由已保留。'};
    redraw();
  };


  const note=ui.notice?h('div',{class:'note',role:'status'},(ui.notice.kind==='error'?'出错：':'提示：')+ui.notice.text):null;
  const btn=(label,cls,fn,dis)=>h('button',{type:'button',class:'btn '+cls,disabled:!!dis,onclick:fn},label);
  const mini=(label,fn,dis)=>h('button',{type:'button',class:'mini',disabled:!!dis,onclick:fn},label);

  const head=h('div',{class:'head'},
    h('div',{class:'ttl'},'整理收件箱'),
    h('div',{class:'steps'},[['1','范围'],['2','审阅'],['3','确认']].map(s=>{
      const n=Number(s[0]);
      return h('button',{type:'button',class:'chip'+(step===n?' on':''),title:s[1],'aria-label':s[1],'aria-pressed':step===n?'true':'false',onclick:()=>go(n)},h('b',{},s[0]),h('span',{class:'lb'},s[1]));
    })));

  let body,foot;
  if(step===1){
    const dfield=(k,lb,al)=>h('label',{class:'df'},h('span',{},lb),h('input',{type:'date',value:range[k]||'','aria-label':al,onchange:e=>setRange(k,e.target.value)}));
    let status;
    if(!job)status=h('div',{class:'muted'},'尚未读取邮件');
    else if(loading)status=h('div',{class:'muted',role:'status'},'读取中…');
    else if(job.status==='error')status=h('div',{class:'note'},'出错：'+mailErr(job.error));
    else status=h('div',{class:'muted'},'已读取 '+all.length+' 封，范围内 '+rows.length+' 封');
    body=h('div',{class:'body'},note,
      h('div',{class:'dates'},dfield('from','从','起始日期'),dfield('to','到','结束日期')),
      h('div',{class:'quick'},mini('近7天',()=>quick(7)),mini('近30天',()=>quick(30))),
      status,
      h('div',{class:'muted fine'},'只读取邮件元数据。AI 建议和归档需平台接入后才能执行。'));
    foot=h('div',{class:'foot'},btn(loading?'读取中…':'读取邮件','pri',readMails,loading),btn('AI 建议','sec',askAi));
  }else if(step===2){
    const allOn=rows.length>0&&rows.every(r=>(plan[r.id]||{}).picked);
    const rowNode=r=>{
      const p=plan[r.id]||{};
      const open=ui.open===r.id;
      return h('li',{class:'row'+(p.picked?' pk':'')+(open?' open':'')},
        h('input',{type:'checkbox',checked:!!p.picked,'aria-label':'选择：'+r.subject,onchange:()=>setPlan(r,{picked:!p.picked})}),
        h('button',{type:'button',class:'main','aria-expanded':open?'true':'false',onclick:()=>{ui.open=open?null:r.id;redraw();}},
          h('span',{class:'sj'},r.subject),
          h('span',{class:'mt'},[r.from,r.day||'无日期'].filter(Boolean).join(' · '))),
        h('span',{class:'pill '+(p.mark||'')},p.mark==='archive'?'归档':(p.mark==='keep'?'保留':'待定')),
        h('div',{class:'det'},
          h('div',{class:'seg',role:'group','aria-label':'建议'},
            h('button',{type:'button','aria-pressed':p.mark==='archive'?'true':'false',onclick:()=>setMark(r,'archive')},'归档'),
            h('button',{type:'button','aria-pressed':p.mark==='keep'?'true':'false',onclick:()=>setMark(r,'keep')},'保留')),
          h('input',{class:'rsn',type:'text',value:p.reason||'',placeholder:'理由，可修改','aria-label':'理由',onchange:e=>setPlan(r,{reason:e.target.value})})));
