    if(!rows.length){
      empty=h('div',{class:'muted'},loaded?'所选日期范围内没有邮件。':(job&&job.status==='error'?mailErr(job.error):'还没有邮件，请先到「范围」读取。'));
    }
    body=h('div',{class:'body'},note,
      h('div',{class:'tool'},h('span',{class:'muted'},'共 '+rows.length+' 封，已勾 '+picked.length),mini(allOn?'清空':'全选',()=>pickAll(!allOn),!rows.length)),
      h('div',{class:'muted fine'},'AI 建议未接入，建议和理由由你自己判断、填写。'+(!loaded&&rows.length?'（以下是已保存的标记，尚未重新读取）':'')),
      empty,
      rows.length?h('ul',{class:'rows'},rows.map(rowNode)):null);
    foot=h('div',{class:'foot'},btn('去确认（'+picked.length+'）','pri',()=>go(3),!picked.length));
  }else{
    const cNode=r=>h('li',{class:'row c'},
      h('div',{class:'cm'},
        h('span',{class:'sj'},r.subject),
        h('span',{class:'mt'},[r.from,r.day].filter(Boolean).join(' · ')||'—'),
        h('span',{class:'rs'},r.reason?('理由：'+r.reason):'未填写理由')),
      mini('移出',()=>setPlan(r,{picked:false})));
    body=h('div',{class:'body'},note,
      h('div',{class:'muted'},'待归档 '+picked.length+' 封'+((range.from&&range.to)?('（'+range.from+' 至 '+range.to+'）'):'')),
      picked.length?h('ul',{class:'rows'},picked.map(cNode)):h('div',{class:'muted'},'还没有勾选邮件，请回到「审阅」勾选。'),
      h('div',{class:'res'},h('b',{},'归档结果：'),'暂无。归档接口未接入，确认后也不会改动邮箱，不会出现成功或失败，单独重试暂不可用。'));
    foot=h('div',{class:'foot'},btn('确认归档 '+picked.length+' 封','pri',doArchive,!picked.length));
  }
  root.append(head,body,foot);
}

